assignments.value:
={{
(() => {
  const text = $node["Telegram Trigger"].json.message.text || '';
  const raw = text.replace(/^\/learn\s+/, '').trim();

  if (!raw) return null;

  if (raw.startsWith('http://') || raw.startsWith('https://')) {
    return raw;
  }

  return 'https://' + raw;
})()
}}

